"""Build the Week 5 browser deck, preserving the course's projection controls."""
from pathlib import Path
from html import escape
from labs_markup import lab
ROOT = Path(__file__).resolve().parents[2]
HERE = Path(__file__).resolve().parent
SAM = 'https://samtools.github.io/hts-specs/SAMv1.pdf'
VCF = 'https://samtools.github.io/hts-specs/VCFv4.5.pdf'
GATK_VCF = 'https://gatk.broadinstitute.org/hc/en-us/articles/360035531692-VCF-Variant-Call-Format'
SV = 'https://gatk.broadinstitute.org/hc/en-us/articles/9022476791323-Structural-Variants'
COLAB = 'https://colab.research.google.com/github/vo-ya/etf_bioinformatics/blob/main/practicals/week-05/exercise.ipynb'
slides = []

def p(s, cls=''):
    return f'<p class="{cls}">{s}</p>'
def table(headers, rows):
    return '<table class="table"><thead><tr>' + ''.join(f'<th>{x}</th>' for x in headers) + '</tr></thead><tbody>' + ''.join('<tr>'+''.join(f'<td>{x}</td>' for x in row)+'</tr>' for row in rows) + '</tbody></table>'
def figure(name, alt, height):
    return f'<figure class="figure"><img src="../../diagrams/week-05/{name}.svg" width="1000" height="{height}" alt="{escape(alt, quote=True)}"></figure>'
def seq(s):
    return '<pre class="sequence">' + escape(s) + '</pre>'
def add(title, body, notes, phase='Evidence', answer=None, source=None, hero=False):
    slides.append(dict(title=title,body=body,notes=notes,phase=phase,answer=answer,source=source,hero=hero))

add('Variant calling and structural variants',p('Which differences from the reference<br>are supported by the reads?', 'subtitle')+p('Week 05 · Synthetic examples throughout', 'small'),
    'Connect the sequence comparisons of Week 2 to the assembly ambiguities of Week 3. Today the task is inference: what sample sequence could explain the observations? The notebook follows class and uses the same small examples. No human sample is analyzed.', 'Variants',hero=True)
add('From placing reads to testing differences', '<div class="flow"><span>Week 2<br>Align reads</span><b>→</b><span>Week 3<br>Reconstruct joins</span><b>→</b><span>Week 5<br>Evaluate variants</span></div>'+p('A mismatch is an observation. What could have produced it?','prompt'),
    'Invite explanations before revealing: a true sample difference, a base-call error, or placement at a similar locus. An assembly can reveal a sequence absent from the chosen reference. Keep reference coordinates distinct from sample sequence.', 'Variants', 'A sample difference, a sequencing error, or an incorrect alignment.')
add('BAM stores reads and their alignments',table(['Format','What is stored'],[['FASTQ','Read sequence and per-base quality; no placement'],['SAM','Readable text records of reads and alignments'],['BAM','Compressed binary representation of SAM data']])+p('Coordinate-sorted BAM + an index → retrieve reads overlapping a region.','lead')+p('Does converting SAM to BAM call variants?','prompt'),
    'Expand SAM as Sequence Alignment/Map and BAM as Binary Alignment/Map. BAM stores the same logical alignment information in a compact binary encoding; view it through suitable software, not as raw text. Headers name reference sequences; records include placement, flags, CIGAR, sequence, qualities, and optional tags. A BAM can also contain unmapped records, and secondary or supplementary alignments mean there need not be exactly one record per read. BAM is not inherently coordinate-sorted; coordinate sorting and a separate BAI or CSI index enable efficient region retrieval. Indexing neither improves alignment nor calls variants. VCF records are downstream inferences.', 'Variants', 'No. The encoding changes; variant calling is a separate analysis.',source=SAM)
add('Decode one alignment before making a pileup',table(['RNAME','POS','MAPQ','CIGAR','SEQ','QUAL'],[['toy','99','60','5M','TCGAT','DDDDD']])+p('Selected fields from a SAM text view of one forward-strand record.','small')+seq('Position    99 100 101 102 103\nReference    T   C   A   A   T\nRead         T   C   G   A   T')+p('Which letter enters the pileup at position 101?','prompt'),
    'This is a selected-field view, not a complete SAM record or literal BAM bytes. A full illustrative record is r07, FLAG 0, RNAME toy, POS 99, MAPQ 60, CIGAR 5M, RNEXT *, PNEXT 0, TLEN 0, SEQ TCGAT, QUAL DDDDD (tab-separated). FLAG 0 denotes a forward mapped unpaired read in this example. SAM POS is 1-based; a BAM library may expose a 0-based start, here 98. Five M operations consume five query and five reference bases, spanning 99–103. M permits either a match or mismatch; it does not mean five identical bases. Per-base QUAL D decodes as ASCII 68 minus 33 = Q35. MAPQ 60 describes placement, not individual letters. The third query base G contributes at 101. A pileup groups observations from many records at that reference coordinate; it is computed from records rather than stored as a single BAM column.', 'Variants', 'G, with base Q35. MAPQ 60 concerns the placement; 5M permits mismatches.',source=SAM)
add('One base, a short gap, or a new arrangement',table(['Change','Reference','Sample'],[['SNV','ACGT','ATGT'],['Small deletion','ACGT','AGT'],['Larger rearrangement','A → B → C → D','A → B → D']])+p('Letters in the last row stand for long sequence blocks.','small'),
    'SNV means single-nucleotide variant. An insertion adds sample sequence relative to the reference; a deletion removes it. SV definitions commonly use a size threshold around 50 bases, but junction structure matters too. These are sequence differences, not claims about functional harm.', 'Variants')
add('Two chromosome copies, three simple genotypes',table(['Diploid genotype','Copies at this site','Description'],[['0/0','A + A','Both reference'],['0/1','A + G','One of each'],['1/1','G + G','Both alternate']])+p('Here REF=A and the first ALT=G.','small'),
    'Use a simple diploid autosomal locus with one candidate ALT throughout this block. Define homologous copies and heterozygosity. Real samples can have different ploidy, mixtures, or more than one ALT. VCF 0 and 1 are allele indices, not bases or read counts; slash means phase is not supplied.', 'Variants', source=VCF)
add('The reference is a coordinate system',p('A reference allele is the allele in the selected reference sequence.','lead')+p('It need not be the common allele, the ancestral allele, or the allele with no biological effect.','small')+p('What must accompany “A→G at position 101”?','prompt'),
    'Ask for reference assembly or synthetic reference ID, contig, coordinate convention, and REF/ALT. If comparing callsets, matching a number alone is insufficient. Our examples use an invented contig called toy and 1-based VCF positions.', 'Variants', 'Reference identity, chromosome/contig, and coordinate convention.')
add('The workflow preserves different evidence', '<div class="flow"><span>Reads<br>FASTQ</span><b>→</b><span>Alignments<br>BAM / CRAM</span><b>→</b><span>Calls<br>VCF</span></div>'+p('Check reads and mappings → infer alleles and genotypes → filter and annotate.','lead'),
    'Relate FASTQ to Week 1. Alignment files retain placements and qualities. VCF summarizes proposed variants and per-sample values; it does not contain all the supporting read context. Production processing includes appropriate duplicate handling and assay-specific validation. We inspect prepared observations rather than installing a full pipeline.', 'Variants')
add('A pileup collects observations at one position',figure('pileup','Twelve synthetic fragments: six A and six G at reference position 101.',395),
    'Read the position labels at the top. Each row is a different invented fragment, with its bases expressed in reference orientation. The same read can contribute to several reference positions, but here we inspect only position 101. There are no duplicated molecules in this toy.', 'Evidence')
add('Allele fraction is a summary of retained reads',p('6 G / (6 A + 6 G) = <strong>0.5</strong>','big-definition')+p('Does 0.5 by itself establish genotype 0/1?','prompt'),
    'Under equal sampling at a simple diploid heterozygous site, the expected fraction is near half. An observed half can also arise from mixtures or errors. Sampling variation means true heterozygotes need not show exactly half. This read fraction differs from population allele frequency.', 'Evidence', 'No. Inspect quality, mapping, independence, and sample assumptions.')
add('Base confidence and placement confidence differ', '<div class="two-columns"><div><h3>Base quality</h3><p>How uncertain is the reported letter?</p><p>Q20 corresponds to an estimated base-error probability of 0.01.</p></div><div><h3>Mapping quality</h3><p>How uncertain is this placement?</p><p>A clear G can still be aligned to the wrong repeated region.</p></div></div>',
    'Recall the Phred equation from Week 1: Q=-10 log10(error probability). Mapping quality concerns placement, with aligner-specific conventions and calibration; a SAM MAPQ of 255 can mean unavailable. Our toy uses ordinary numeric values, not this sentinel. High base quality does not repair ambiguous mapping.', 'Evidence')
add('Which observations survive the filters?',table(['Observations','Base Q','Mapping Q','Keep?'],[['8 A','35','60','Predict'],['4 G','10','60','Predict'],['2 G','35','5','Predict']])+p('Teaching rule: base Q ≥ 20 <strong>and</strong> mapping Q ≥ 30.','prompt'),
    'Have students count before and after filtering. Raw G fraction is 6/14. Only the eight A observations pass both inclusive thresholds, so the retained G fraction is 0/8. These thresholds are illustrative, not universal. Do not report no alternate support as proof that the sample contains no variant.', 'Evidence', 'Raw: 6/14 ≈ 0.429. Retained: 0/8 = 0.')
add('A and C have equal fractions, different strand support',table(['Site','A reads','G reads','G forward / reverse'],[['A','6','6','3 / 3'],['C','6','6','6 / 0']])+p('What would you inspect next at C?','prompt'),
    'Both sites pass the toy quality filters and have G fraction 0.5. C has strand imbalance. Inspect independent reverse-oriented fragments, read starts, cycle positions, and local alignment. Small counts can be imbalanced by chance; do not impose a universal discard rule. The later count-only likelihood model cannot distinguish these sites.', 'Evidence', 'Independent fragments on the other strand and the local alignment context.')
add('Many read records may share one original molecule',p('One original fragment → PCR copies → many read records','lead')+p('Would 20 duplicate records provide 20 independent observations?','prompt'),
    'No. Relate to library preparation in Week 1. Distinguish technical duplication from independent sampled molecules. Overlapping mates can also observe the same molecule and base twice. Handling depends on assay and available molecular identifiers. In our notebook each synthetic observation is independent by construction.', 'Evidence', 'No. Count and model the evidence with its molecular dependence in mind.')
add('Compare predictions from candidate genotypes',table(['Genotype','Expected G fraction in our toy'],[['0/0','e = 0.01'],['0/1','0.5'],['1/1','1 − e = 0.99']])+p('Binary A/G errors, independent observations, equal chromosome sampling.','small'),
    'This is an explicitly binary model: errors flip A to G or G to A. It is not the usual four-base error model where error can distribute across three alternatives. Mapping is assumed correct and the error rate is known and equal across reads. No priors are used. All those simplifications matter.', 'Genotypes')
add('Which genotype best explains these counts?',p('L = (1 − p)<sup>6</sup> × p<sup>6</sup>','formula')+table(['Genotype','p = P(G)','log₁₀ likelihood'],[['0/0','0.01','−12.026'],['0/1','0.50','−3.612'],['1/1','0.99','−12.026']]),
    'Compute log10 L = r log10(1-p)+a log10(p). Six A and six G favor 0/1 among these candidates under this model. We write the likelihood of the observed sequence; a binomial coefficient for counts is shared and would cancel in comparisons. Likelihood is not posterior probability. This simplified output is not a calibrated QUAL or GQ.', 'Genotypes', '0/1 fits best under the stated assumptions; this is not a guarantee.')
add('Missing observations do not support 0/0',table(['Retained observations','Conclusion in the toy'],[['1 A + 1 G','0/1 fits best, but there is little evidence'],['6 A + 6 G','Same best genotype, stronger likelihood contrast'],['No observations','All candidates have equal likelihood']]),
    'For 1+1 observations Lhetero/Lhom=0.25/0.0099≈25.25. For 6+6 the ratio is that value to the sixth power, about 2.59e8. When both counts are zero the likelihood is one for every genotype. A best-fit label without evidence strength can be misleading. The notebook returns None for an undefined read fraction.', 'Genotypes')
add('A repeat permits several gap placements',seq('Reference   CAAAG\nAlignment 1 C-AAG\nAlignment 2 CA-AG\nAlignment 3 CAA-G')+p('Each aligned sample spells CAAG after removing the gap.','small'),
    'Ask students to remove the gap in every line and compare. The sample lost one A, but the identical run does not identify a unique historical A molecule or a single alignment placement. Equivalent VCF representations need normalization before exact record comparisons. Left normalization is a representation convention, not proof of a unique mutational history.', 'Genotypes', 'The sample sequence is clear; the gap position inside the repeat is ambiguous.')
add('Local assembly compares candidate sequences', '<div class="flow"><span>Reads near<br>a candidate</span><b>→</b><span>Candidate<br>haplotypes</span><b>→</b><span>Compare read<br>support</span></div>'+p('A new join may explain several mismatches and gaps together.','lead'),
    'Connect to Week 3 graphs and the Week 4 alignment simulator. A haplotype is a candidate sequence for one chromosome copy across the local region. Many callers use local haplotypes rather than treating every column independently. This is conceptual; students do not implement a production assembler. Repeats can still leave multiple candidate paths.', 'Genotypes')
add('Structural changes alter sequence content or joins',figure('sequence-changes','Oriented blocks showing deletion, duplication, and insertion compared with a reference.',360),
    'Blocks denote long regions, not bases. Read each row against the reference: deletion removes C; tandem duplication adds another C; insertion adds X. Copy-number variants include losses and gains, but some structural changes preserve copy number. Around 50 bp is a common operational size boundary; larger scale does not automatically imply a larger biological effect.', 'Structure', source=SV)
add('A copy-number ratio needs a baseline',table(['Ideal total copies','Relative to diploid baseline'],[['1 copy','1/2 = 0.5'],['2 copies','2/2 = 1.0'],['3 copies','3/2 = 1.5']])+p('Assume comparable sampling, mappability, and a homogeneous sample.','small'),
    'Expected depth is approximately proportional to copy number only under these assumptions. A heterozygous deletion leaves one copy; it need not produce zero depth. Unequal library sizes need normalization. Mixtures and mapping bias complicate ratios. Do not use this table as an unconditional inference rule.', 'Structure')
add('An inversion reverses order and orientation',figure('inversion','C and D become reverse D then reverse C; copy number is unchanged.',365),
    'The reverse complement is required when representing the inverted DNA on the same reference strand. Block arrows communicate orientation, not just order. A balanced inversion can preserve depth, so depth-only detection misses it. Inspect breakpoint-spanning alignments and pair orientations.', 'Structure', source=SV)
add('A translocation joins different chromosomes',figure('translocation','Two toy chromosomes exchange terminal regions C and Z.',375),
    'This is a simplified reciprocal, balanced exchange. New B–Z and Y–C junctions connect regions previously on different chromosomes. Other translocations can be unbalanced. Pair placements on different chromosomes are candidates, but chimeric library fragments and mapping errors can mimic them. Require consistent independent support.', 'Structure', source=SV)
add('Does depth identify the rearrangement?',figure('coverage','Four 100-base windows have mean depth ten while flanks and control average twenty.',425),
    'Use the same data as notebook task 4. Region [400,800) contains windows starting at 400,500,600,700 with values 10,9,11,10. Flank values sum to 160 over eight windows. Ratio=10/20=0.5. Coordinates are 0-based boundaries. Window resolution does not establish exact breakpoints.', 'Structure')
add('A deletion increases the reference span',figure('deletion-evidence','A 300-base sample fragment maps across 700 reference bases; a split read joins boundaries 400 and 800.',420),
    'Top pair: read alignments occupy [250,300) and [900,950), inward-facing. Reference outer span is 700; removing the 400-base interval gives a 300-base sample fragment. The library normally has spans near 300 in this toy. Bottom split read has two 20-base pieces at [380,400) and [800,820). It is a different molecule from the paired example. Coordinates are illustrative and error-free.', 'Structure')
add('Split reads test a proposed new adjacency',seq('Reference:  left flank | 400-base region | right flank\nSample:     left flank | right flank\nSplit read:        [20 bases][20 bases]')+p('What does the read contribute beyond a depth ratio?','prompt'),
    'A sequence that crosses the new adjacency can constrain the joined flanks and orientation. The alignments must be credible and independently supported. Repeats or microhomology can leave a range of possible breakpoint positions. Depth is regional evidence; a split read can provide junction evidence.', 'Structure', 'Sequence evidence linking the two flanks, with breakpoint uncertainty.')
add('Assembly can bridge a larger rearrangement',seq('Read 1       left flank ─────\nRead 2              ───── new join ─────\nRead 3                              ───── right flank\nContig       left flank ── new join ── right flank')+p('Align the assembled contig back to the reference.','lead'),
    'This schematic is not a literal sequence alignment. A contig or long read spanning a junction supplies longer context. For inversions or translocations its pieces can align with changed orientations or chromosomes. Assembly errors and repeats remain possible; a contig is evidence, not automatic validation. Link to the ambiguous joins from Week 3.', 'Structure')
add('Combine evidence that answers different questions',table(['Evidence','Question'],[['Read depth','Is the amount of mapped sequence different?'],['Paired ends','Is fragment geometry unusual on the reference?'],['Split reads','Which flanks meet within a read?'],['Assembly / long reads','Can a longer sequence span the proposed arrangement?']]),
    'Evidence categories are not statistically independent when derived from the same molecules. Do not multiply apparent confirmations blindly. Different callers combine them in different ways. Ask students which evidence would be weakest for a balanced inversion: ordinary depth can be unchanged.', 'Structure', source=SV)
add('The same depth profile can have two explanations', '<div class="two-columns"><div><h3>Candidate deletion</h3><p>One copy is absent.</p><p>Depth ratio ≈ 0.5.</p></div><div><h3>Mapping loss</h3><p>Both copies exist, but many reads fail to map.</p><p>Depth ratio ≈ 0.5.</p></div></div>'+p('What observation would help choose between them?','prompt'),
    'A matched control and mappability review help assess regional biases, but sample-specific divergence may still cause mapping loss. Seek reads or assembled sequence spanning the new junction, and inspect alternative placements. This is the central interpretive task of the notebook.', 'Structure', 'Credible, independent junction-spanning sequences and a mapping-context check.')
add('VCF separates locus, alleles, and sample fields', '<pre class="vcf">CHROM  POS  REF  ALT  QUAL  FILTER  FORMAT    SAMPLE\ntoy    101  A    G    .     PASS    GT:AD:DP  0/1:6,6:12</pre>'+p('Selected columns shown; the full notebook file includes headers, ID, and INFO.','small'),
    'Read from left to right. Position 101 is 1-based. QUAL is unknown here, indicated by dot. FORMAT identifies the meanings of the colon-separated sample values. PASS is a supplied example label, not inferred by our notebook; real filtering rules belong in the header and workflow documentation.', 'Records',source=VCF)
add('GT, AD, and DP answer different questions',table(['Field','Example','Meaning'],[['GT','0/1','Inferred allele pair, unphased'],['AD','6,6','Reference then alternate allele depths'],['DP','12','Sample depth at the position']])+p('The observed read fraction here is 6 / (6 + 6) = 0.5.','prompt'),
    'GT is a genotype, not the raw fraction. FORMAT order must be read from the record rather than assumed. Real DP and AD definitions may count different sets of reads, so equality is not guaranteed. This synthetic record deliberately uses equal totals. Multiple alternate alleles require more entries and different allele indices.', 'Records', source=GATK_VCF)
add('Read the allele change and its coordinate',seq('VCF:     POS=501   REF=AT   ALT=A\nPosition:        501  502\nReference:   ...  A    T  ...\nSample:      ...  A    -  ...')+p('Which base is deleted, and where does Python index it?','prompt'),
    'VCF represents the allele replacement starting at 501. A remains as the left anchor; T at position 502 is deleted, corresponding to Python index 501. The anchor at 501 corresponds to index 500. This is a separate small indel, not the 400-base coverage example. VCF supports symbolic SV alleles and breakends, outside the core parser.', 'Records', 'T at 1-based position 502 is deleted; its Python index is 501.',source=VCF)
add('Quality, filtering, and missing values differ',table(['Label','What to ask'],[['QUAL','How confident is the site-level assertion?'],['GQ','How confident is this sample genotype?'],['PASS','Which filters were applied and passed?'],['.','Is this value missing or filtering not applied?']]),
    'Do not conflate base quality, mapping quality, site QUAL, and sample GQ. They concern different claims. Dot meaning depends on the field: missing QUAL is unknown; FILTER dot means filters have not been applied. Our toy supplies no calibrated QUAL or GQ. PASS does not mean clinically benign or experimentally validated.', 'Records',source=GATK_VCF)
add('Calling a variant and explaining its effect are separate', '<div class="flow"><span>Call<br>Sequence difference</span><b>→</b><span>Annotate<br>Genomic context</span><b>→</b><span>Investigate<br>Biological effect</span></div>'+p('An indel can affect a coding frame only in the relevant coding transcript.','lead'),
    'Ask where the variant falls: coding exon, splice region, regulatory region, or another context. Consequence depends on transcript and allele representation. A coding indel whose length is not divisible by three can change the reading frame. Annotation is a hypothesis about consequence, not proof of an effect on the cells. No clinical classification is performed.', 'Records')
add('Case 1: which site needs a different follow-up?',table(['Site','After default quality filters','Other observation'],[['A','6 A, 6 G','G supported on both strands'],['B','8 A, 0 G','All G failed a quality threshold'],['C','6 A, 6 G','G only on the forward strand']])+p('State an observation and a next check for each site.','prompt'),
    'A has balanced alternate evidence: inspect mapping context and molecular independence before accepting a call. B loses all alternate support under the stated rule; this is not proof of absence in poorly sampled or biased data. C requires examination of strand and read-position context despite the same fraction as A. Give pairs time to explain.', 'Evidence', 'Equal fractions can conceal different evidence; filtering changes what was observed.')
add('Case 2: how strongly does the deletion case hold?',p('Depth ratio 0.5 in [400,800).<br>Independent pairs have reference spans near 700 bp.<br>Split reads join the 400 and 800 boundaries.','lead')+p('The usual fragment span is about 300 bp. What is the shared explanation?','prompt'),
    'A 400-base loss on one chromosome is coherent with all three observations in the ideal diploid toy. The pair span excess is 700−300=400. Confidence still depends on mapping ambiguity and independence. Precise boundaries here are supplied by the synthetic split alignments, not inferred from the coarse depth bins alone.', 'Evidence', 'A candidate 400-base heterozygous deletion; check mapping and junction support.')
add('What can the reads establish?', '<ol class="question-list"><li>Why is an alternate-read fraction <strong>not a genotype</strong>?</li><li>Why can a balanced inversion have <strong>ordinary depth</strong>?</li><li>Why does <strong>PASS</strong> not establish a functional effect?</li></ol>',
    'Expected answers: read fractions depend on errors, mapping, sampling, and sample composition; genotype inference needs a model and context. An inversion can change orientation without changing copy number. PASS records filter status, while functional interpretation needs transcript and biological evidence. Ask students to name one concrete observation supporting each answer.', 'Evidence')
add('Exercise: inspect, change, and explain',p('Count alleles → change quality filters → compare strands.<br>Plot regional depth → interpret two VCF records.','lead')+p('Short runnable cells, small edits, and written explanations.<br>The genotype-likelihood extension is optional.','small')+f'<div class="inline-links"><a href="{COLAB}" target="_blank" rel="noopener">Open in Colab</a><a href="../../practicals/week-05/exercise.ipynb" download>Download notebook</a><a href="../../weeks/week-05.html">Week 5 guide</a><a href="../../practicals/week-05/bam_exercise.ipynb" download>Additional BAM exercise</a></div>',
    'The separate required homework takes 60–90 minutes. Students save their own copy and work cell by cell. The notebook embeds data and helpers and does not install a caller or fetch a real genome. Download/upload if the GitHub Colab link is not yet published. The instructor edition includes explanations. Optional likelihood work takes additional time.', 'Evidence')

assert len(slides) == 38
header='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="Week 5: variant calling, read evidence, genotypes, structural variants, and VCF interpretation."><title>Week 5 — Variant calling and structural variants</title><link rel="stylesheet" href="slides.css"><script src="slides.js" defer></script><link rel="stylesheet" href="../../assets/week5-interactions.css"><script src="../../assets/week5-core.js" defer></script><script src="../../assets/week5-interactions.js" defer></script></head><body><a class="skip-link" href="#deck">Skip to slides</a><main class="deck" id="deck" aria-label="Week 5 presentation"><div class="stage">'''
parts=[header]
activities={12:'pileup',16:'likelihood',20:'structure',24:'coverage',32:'vcf'}
for i,s in enumerate(slides,1):
    title=escape(s['title'])
    heading=f'<h1>{title}</h1>' if s['hero'] else f'<h2>{title}</h2>'
    journey=''.join(f'<li'+(' aria-current="step"' if phase==s['phase'] else '')+f'>{phase}</li>' for phase in ['Variants','Evidence','Genotypes','Structure','Records'])
    source=f'<a href="{s["source"]}" target="_blank" rel="noopener">Source</a>' if s['source'] else '<a href="../../weeks/week-05.html">Week 5 guide</a>'
    answer=f'<p class="answer-line" data-reveal="1">{s["answer"]}</p>' if s['answer'] else ''
    content=s['body']+answer
    steps=1 if s['answer'] else 0
    if i in activities:
        content=lab(activities[i],content.replace(' data-reveal="1"',''))
        steps=0
        s['notes'] += ' Interactive activity: ask for a prediction before changing a control. Reset to the worked example before continuing. Controls replace discussion within this block; they add no class time.'
    parts.append(f'''<section class="slide {'hero' if s['hero'] else ''}" id="slide-{i:02}" aria-label="Slide {i}: {escape(s['title'],quote=True)}" data-steps="{steps}"><p class="eyebrow">Week 05 · {s['phase']}</p>{heading}<div class="content">{content}</div><footer class="slide-footer"><ol class="journey" aria-label="Our journey">{journey}</ol>{source}<span class="folio">{i:02}</span></footer><aside class="notes"><p>{s['notes']}</p>{source}</aside></section>''')
# Keep the established accessible controls and shortcut help in sync with Week 3.
tail=(ROOT/'presentations/week-03/index.html').read_text().split('</div></main>',1)[1]
tail=tail.replace('1 / 40','1 / 38').replace('All 40 slides','All 38 slides')
parts.append('</div></main>'+tail)
(HERE/'index.html').write_text('\n'.join(parts)+'\n')
print('Wrote 38-slide Week 5 deck')
